const api=WildRideMember,message=document.getElementById('member-message');let currentProgress={journal:{},revision:0};
function notify(text,error=false){message.textContent=text;message.classList.toggle('error',error)}
function safeGuest(){try{const raw=JSON.parse(localStorage.getItem('wildride-practice-v1')||'{}');const clean={};SKILLS.forEach(s=>{const v=raw?.[s.id];if(v&&['new','learning','practiced'].includes(v.status)&&(v.status!=='new'||v.notes))clean[s.id]={status:v.status,notes:typeof v.notes==='string'?v.notes.slice(0,1200):'',updatedAt:typeof v.updatedAt==='string'?v.updatedAt.slice(0,50):''}});return clean}catch{return {}}}
function showAuth(register=false){document.getElementById('auth-section').hidden=false;document.getElementById('dashboard-section').hidden=true;document.getElementById('login-form').hidden=register;document.getElementById('register-form').hidden=!register;document.getElementById('show-login').setAttribute('aria-pressed',!register);document.getElementById('show-register').setAttribute('aria-pressed',register)}
async function dashboard(member){loadMemberAvatar(member);document.getElementById('auth-section').hidden=true;document.getElementById('dashboard-section').hidden=false;document.getElementById('welcome-name').textContent=member.name+'，歡迎回來。';document.getElementById('member-email').textContent=member.email+(member.emailVerified?' · Email 已驗證':' · Email 尚未驗證');for(const [field,value]of Object.entries({name:member.name,bike:member.profile.bike||'',experience:member.profile.experience||'',goal:member.profile.goal||''}))document.getElementById('profile-'+field).value=value;currentProgress=await api.request('progress');const values=Object.values(currentProgress.journal);document.getElementById('member-practiced').textContent=values.filter(v=>v.status==='practiced').length;document.getElementById('member-learning').textContent=values.filter(v=>v.status==='learning').length;const host=document.getElementById('member-levels');host.replaceChildren();SKILL_LEVELS.forEach(l=>{const all=SKILLS.filter(s=>s.level===l.id),done=all.filter(s=>currentProgress.journal[s.id]?.status==='practiced').length;const row=document.createElement('div');row.className='level-progress';const label=document.createElement('b');label.textContent=l.id==='SP'?'獨立專項':l.id;if(l.id!=='SP'){const img=document.createElement('img');img.src='assets/levels/'+l.id.toLowerCase()+'.svg';img.alt='';label.prepend(img)}else{const img=document.createElement('img');img.src='assets/specialties/sp.svg';img.alt='';label.prepend(img)}const status=document.createElement('span');status.textContent=`${done} / ${all.length} 項自記練習`;row.append(label,status);host.append(row)});document.getElementById('import-section').hidden=Object.keys(safeGuest()).length===0;await refreshMemberOperations();notify('已登入。技能紀錄、訂單與教練核發證書已連結至此帳號。')}
async function formAction(form,action){const submit=form.querySelector('button[type=submit]');submit.disabled=true;try{await action()}catch(e){notify(e.message,true)}finally{submit.disabled=false}}
document.getElementById('show-login').addEventListener('click',()=>showAuth(false));document.getElementById('show-register').addEventListener('click',()=>showAuth(true));document.getElementById('login-form').addEventListener('submit',e=>{e.preventDefault();formAction(e.target,async()=>{const result=await api.request('login',{email:document.getElementById('login-email').value,password:document.getElementById('login-password').value});e.target.reset();if(result.needsConfirmation){showAuth();notify('註冊資料已送出，請查看 Email 驗證信。完成驗證後再登入。');return}await dashboard(result.member)})});document.getElementById('register-form').addEventListener('submit',e=>{e.preventDefault();formAction(e.target,async()=>{const password=document.getElementById('register-password').value;if(password!==document.getElementById('register-confirm').value)throw Error('兩次密碼輸入不一致。');const result=await api.request('register',{name:document.getElementById('register-name').value,email:document.getElementById('register-email').value,password});e.target.reset();if(result.needsConfirmation){showAuth();notify('註冊資料已送出，請查看 Email 驗證信。完成驗證後再登入。');return}await dashboard(result.member)})});document.getElementById('profile-form').addEventListener('submit',e=>{e.preventDefault();formAction(e.target,async()=>{const data=Object.fromEntries(['name','bike','experience','goal'].map(key=>[key,document.getElementById('profile-'+key).value]));const result=await api.request('profile',data);await dashboard(result.member);notify('個人資料已儲存。')})});document.getElementById('logout').addEventListener('click',async e=>{e.target.disabled=true;try{await api.request('logout',{});showAuth();notify('已登出。會員筆記仍保留於原帳號。')}catch(err){notify(err.message,true)}finally{e.target.disabled=false}});document.getElementById('import-guest').addEventListener('click',async e=>{if(!confirm('將此瀏覽器的訪客紀錄合併到目前帳號？同名技能優先保留帳號紀錄。'))return;e.target.disabled=true;try{const latest=await api.request('progress');const merged={...safeGuest(),...latest.journal};await api.request('progress',{journal:merged,revision:latest.revision});await dashboard(api.member);notify('訪客紀錄已合併至此帳號，原訪客紀錄仍保留。')}catch(err){notify(err.message,true)}finally{e.target.disabled=false}});
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.textContent=open?'關閉 ×':'選單 ＋'});api.session().then(async s=>{if(s.member)await dashboard(s.member);else{showAuth();notify('登入或建立帳號，開始保存自己的技能紀錄。')}}).catch(e=>{showAuth();notify(e.message+(api.mode==='local'?' 請開啟本機會員網站。':' 請確認 Supabase 資料表及登入設定。'),true)});
